import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import DangNhap from './trang/DangNhap';

// Hai trang Dashboard "cứng" tạm thời để bạn test phân luồng
const DashboardQuanLy = () => (
  <div style={styles.dashboardContainer}>
    <h1 style={{ color: '#a52a2a' }}>🏠 DASHBOARD QUẢN LÝ</h1>
    <p>Chào Sếp! Đây là khu vực điều hành hệ thống A&RMS.</p>
  </div>
);

const DashboardCuDan = () => (
  <div style={styles.dashboardContainer}>
    <h1 style={{ color: '#2e7d32' }}>🌳 DASHBOARD CƯ DÂN</h1>
    <p>Chào Cư dân! Chúc bạn một ngày tốt lành tại A&RMS.</p>
  </div>
);

function App() {
  return (
    <Router>
      <Routes>
        {/* 1. Vào trang là tự đẩy sang đăng nhập */}
        <Route path="/" element={<Navigate to="/auth" />} />

        {/* 2. Trang Auth (Đăng nhập & Đăng ký lật mặt) */}
        <Route path="/auth" element={<DangNhap />} />

        {/* 3. Phân luồng Dashboard theo vai trò */}
        <Route path="/dashboard-quan-ly" element={<DashboardQuanLy />} />
        <Route path="/dashboard-cu-dan" element={<DashboardCuDan />} />

        {/* 4. Gõ bừa địa chỉ sẽ về lại Đăng nhập */}
        <Route path="*" element={<Navigate to="/auth" />} />
      </Routes>
    </Router>
  );
}

const styles = {
  dashboardContainer: {
    display: 'flex', flexDirection: 'column', justifyContent: 'center', 
    alignItems: 'center', height: '100vh', textAlign: 'center', fontFamily: 'sans-serif'
  }
};

export default App;
